fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // k is 1-based, so convert to 0-based
    let k_zero_based = k - 1;
    
    // Create a new vector with capacity n-1
    let mut new_list = Vec::with_capacity(list.len() - 1);
    
    // Add elements before position k
    new_list.extend_from_slice(&list[0..k_zero_based]);
    
    // Add elements after position k
    new_list.extend_from_slice(&list[k_zero_based + 1..]);
    
    new_list
}